import{_ as r,o,c as a,a2 as e}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"ウェブ検索プロバイダー","description":"","frontmatter":{},"headers":[],"relativePath":"ja/integrations/providers/web-search.md","filePath":"ja/integrations/providers/web-search.md","lastUpdated":1792323081000}'),n={name:"ja/integrations/providers/web-search.md"};function s(d,t,i,l,h,g){return o(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="ウェブ検索プロバイダー" tabindex="-1">ウェブ検索プロバイダー <a class="header-anchor" href="#ウェブ検索プロバイダー" aria-label="Permalink to &quot;ウェブ検索プロバイダー&quot;">​</a></h1><p>Bot に <strong>Search Provider</strong> を接続すると、検索エンジンの API をツールとして使い、会話の中で<strong>リアルタイム</strong>にウェブを検索できるようになります。</p><h2 id="何をするものか" tabindex="-1">何をするものか <a class="header-anchor" href="#何をするものか" aria-label="Permalink to &quot;何をするものか&quot;">​</a></h2><p>各 Search Provider は、特定の検索 API（Brave、Google など）への接続です。設定して Bot に割り当てると、新しい事実が必要なときにモデルが呼び出します。</p><hr><h2 id="サポートされる検索エンジン" tabindex="-1">サポートされる検索エンジン <a class="header-anchor" href="#サポートされる検索エンジン" aria-label="Permalink to &quot;サポートされる検索エンジン&quot;">​</a></h2><p>サイドバーの <strong>ウェブ検索</strong> ページで検索エンジンを設定します。サポートされるエンジンは次のとおりです。</p><table tabindex="0"><thead><tr><th>エンジン</th><th>説明</th></tr></thead><tbody><tr><td><strong>Brave</strong></td><td>プライバシーと速度の面でよく挙げられる</td></tr><tr><td><strong>Bing</strong></td><td>カバレッジが広い</td></tr><tr><td><strong>Google</strong></td><td>定番のウェブ検索</td></tr><tr><td><strong>Tavily</strong></td><td>AI リサーチ向け</td></tr><tr><td><strong>SearxNG</strong></td><td>セルフホストのメタ検索</td></tr><tr><td><strong>DuckDuckGo</strong></td><td>プライバシー重視</td></tr><tr><td>その他</td><td>Sogou、Serper、Jina、Exa、Bocha、Yandex など</td></tr></tbody></table><hr><h2 id="作成する" tabindex="-1">作成する <a class="header-anchor" href="#作成する" aria-label="Permalink to &quot;作成する&quot;">​</a></h2><ol><li>サイドバーの <strong>ウェブ検索</strong> を開きます。</li><li><strong>Add Search Provider</strong> をクリックします。</li><li><strong>Name</strong> と <strong>API Key</strong> を入力します。エンジンによっては <strong>base_url</strong> も必要です（SearxNG など）。</li></ol><p>変更は <strong>Edit</strong>、削除は <strong>Delete</strong> で行います。</p><hr><h2 id="bot-に割り当てる" tabindex="-1">Bot に割り当てる <a class="header-anchor" href="#bot-に割り当てる" aria-label="Permalink to &quot;Bot に割り当てる&quot;">​</a></h2><ol><li><strong>Bots</strong> → Bot</li><li><strong>一般</strong></li><li><strong>Search Provider</strong> のドロップダウンで選択</li><li>保存</li></ol><hr><h2 id="bot-での使われ方" tabindex="-1">Bot での使われ方 <a class="header-anchor" href="#bot-での使われ方" aria-label="Permalink to &quot;Bot での使われ方&quot;">​</a></h2><p><strong>比較的新しく、質問に即した</strong>公開情報が必要なときに検索が実行され、結果が回答に織り込まれます。複数の検索結果をまとめることもあります。具体的な戦略は、モデルとツールの設計によって決まります。</p>',18)])])}const p=r(n,[["render",s]]);export{b as __pageData,p as default};
